/**
 * @method
 * @name scwin.init_entryDefaults
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_entryDefaults = function () {
    let __pc_loadTp = $c.util.getComponent('dma_pageContext');
    if (!__pc_loadTp || typeof __pc_loadTp.get !== 'function') {
        console.warn('[sdd] entry_defaults 대상 부재: dma_pageContext');
    } else if (($c.data.getParameter('loadTp') == null || $c.data.getParameter('loadTp') === '') && (__pc_loadTp.get('loadTp') == null || __pc_loadTp.get('loadTp') === '')) {
        __pc_loadTp.set('loadTp', "0");
    }
};

// 현재 시각 파생값 충전 — as-is JSP 계산분(서버 데이터 아님). 진입점 선두 단계.
/**
 * @method
 * @name scwin.init_nowVars
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
