*/
scwin.init_conds = function () {
    let binds = [{ id: "if_rsltNotiDd", fn: function(){ return ($c.data.readValue("dma_detailData", "rsltNotiDd", { label: "detailData.rsltNotiDd" }) !== ''); } }, { id: "if_procsStatCd", fn: function(){ return ($c.data.readValue("dma_pageContext", "loadTp", { ctx: true, label: "loadTp" }) !== '0' && $c.data.readValue("dma_detailData", "procsStatCd", { label: "detailData.procsStatCd" }) !== '30'); } }, { id: "btn_RetrRequest", fn: function(){ return ($c.data.readValue("dma_pageContext", "loadTp", { ctx: true, label: "loadTp" }) !== '0' && ($c.data.readValue("dma_detailData", "procsStatCd", { label: "detailData.procsStatCd" }) !== '30' && $c.data.readValue("dma_detailData", "procsStatCd", { label: "detailData.procsStatCd" }) !== '11') && ($c.data.readValue("dma_detailData", "skilValuProgStatCd", { label: "detailData.skilValuProgStatCd" }) !== '05' &&  $c.data.readValue("dma_detailData", "skilValuProgStatCd", { label: "detailData.skilValuProgStatCd" }) !== '04')); } }, { id: "btn_Delete", fn: function(){ return ($c.data.readValue("dma_detailData", "procsStatCd", { label: "detailData.procsStatCd" }) === '30'); } }, { id: "btn_Register_2", fn: function(){ return ($c.data.readValue("dma_detailData", "procsStatCd", { label: "detailData.procsStatCd" }) === '30' || $c.data.readValue("dma_detailData", "procsStatCd", { label: "detailData.procsStatCd" }) === '35' || $c.data.readValue("dma_detailData", "procsStatCd", { label: "detailData.procsStatCd" }) === '37'); } }, { id: "btn_Register", fn: function(){ return ($c.data.readValue("dma_pageContext", "loadTp", { ctx: true, label: "loadTp" }) === '0'); } }];
