// 제너레이터 채움 — 진입점(onpageload)에서 순차 실행. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
/**
 * @method
 * @name scwin.init_fillGen
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.init_fillGen = function () {
    let __genFills = [{ genId: "c_foreach_449", entity: "dlt_attachList14", countIds: [], cells: [{ childId: "btn_DownloadFile_8", fn: function (__v, __i) { return String(__v("attachFileNm")); } }] }];
    let gf = __genFills;
    for (let g = 0; g < gf.length; g++) {
        let f = gf[g];
        let gen = $c.util.getComponent(f.genId);
        let ds = $c.util.getComponent(f.entity);
        if (!gen || !ds || !ds.getTotalRow) { continue; }
        let n = ds.getTotalRow();
        if (!n) { continue; }
        // 멱등 — 이미 채워진 제너레이터는 건너뛴다(플래그 없이 컴포넌트 상태로 판단).
        if (gen.getLength && gen.getLength() > 0) { continue; }
        let __row = 0;
        let __cell = function (col) { let v = ds.getCellData(__row, col); return (v === undefined || v === null) ? '' : v; };
        for (let i = 0; i < n; i++) {
            __row = i;
            gen.insertChild(i);
            for (let c = 0; c < f.cells.length; c++) {
                let ch = gen.getChild(i, f.cells[c].childId);
                if (!ch || !ch.setValue) { continue; }
                ch.setValue(f.cells[c].fn(__cell, i));
            }
            for (let k = 0; k < f.countIds.length; k++) {
                let cn = gen.getChild(i, f.countIds[k]);
                if (cn && cn.setValue) { cn.setValue(String(i + 1)); }
            }
        }
    }
};

