 * @author Inswave
 * @date 2026. 09. 06
 * @param chkObj
 * @returns
 * @hidden N
*/
scwin.fn_chkDuplicateExcInstCd = async function (chkObj) {
    if (scwin.selExcInst > 1) {
        let cdArr = $c.util.getComponent('slc_listExcInstCd0');
        let chkDupFlag = false;
        for (let i = 0; i < scwin.selExcInst; i++) {
            if (chkObj !== cdArr[i] && chkObj.value === cdArr[i].value) {
                chkDupFlag = true;
                break;
            }
        }
        if (chkDupFlag) {
            await $c.win.alert("제척기관은 중복하여 선택할 수 없습니다.");
            chkObj.selectedIndex = 0;
            chkObj.value = "";
            chkObj.focus();
            return false;
        }
    }
    if (chkObj.value === '' + $c.data.readValue("dma_detailData", "skil_valu_inst_cd1", { silent: true }) + '' || chkObj.value === '' + $c.data.readValue("dma_detailData", "skil_valu_inst_cd2", { silent: true }) + '') {
        await $c.win.alert("평가기관에 등록된 기간은 선택할 수 없습니다.");
        chkObj.selectedIndex = 0;
        return false;
    }
    return true;
};


