 * @name scwin.fn_Register
 * @author Inswave
 * @date 2026. 09. 06
 * @param val srtMsg
 * @returns
 * @hidden N
*/
scwin.fn_Register = async function (val, srtMsg) {
    let frm = (document.insertForm || { elements: [] });
    if (await scwin.checkForm(frm)) {
        $c.util.getComponent("dma_RegisterReq").set("corpRegNo", $c.util.getComponent('ipt_corpRegNo1').getValue()+ $c.util.getComponent('ipt_corpRegNo2').getValue());
        $c.util.getComponent("dma_RegisterReq").set("bzRegNo", $c.util.getComponent('ipt_bzRegNo1').getValue()+ $c.util.getComponent('ipt_bzRegNo2').getValue()+ $c.util.getComponent('ipt_bzRegNo3').getValue());
        $c.util.getComponent("dma_RegisterReq").set("Zipcd", $c.util.getComponent('ipt_Zipcd').getValue());
        $c.util.getComponent("dma_RegisterReq").set("ComAddr", $c.util.getComponent("dma_RegisterReq").get("ComAddr"));
        $c.util.getComponent("dma_RegisterReq").set("AssgnApplDd", $c.util.getComponent("dma_RegisterReq").get("AssgnApplDd"));
        if (($c.util.getComponent('ipt_addExcInstNm').getValue() == null ? '' : String($c.util.getComponent('ipt_addExcInstNm').getValue())) === '') {
            $c.util.getComponent("dma_RegisterReq").set("addExcInstYn", "N");
        } else {
