        if (await $c.win.confirm(srtMsg + '하시겠습니까?')) {
            $c.win.moveUrl("/jldfil59400/jldfil59400.xml", { "zipcd": $c.util.getComponent('ipt_Zipcd').getValue(), "comAddr": $c.util.getComponent("dma_RegisterReq").get("ComAddr"), "assgnApplDd": $c.util.getComponent("dma_RegisterReq").get("AssgnApplDd"), "addExcInstYn": "N", "method": val });
        }
    }
};


