    __vFields["ipt_faxNo"] = { required: true, format: 'phone' };
    __vFields["ipt_specyValuIndClssNm"] = { required: true };
    __vFields["ipt_apctNm"] = { required: true };
    __vFields["ipt_apctTelNo1"] = { required: true };
    __vFields["ipt_apctTelNo2"] = { required: true };
    __vFields["ipt_apctTelNo3"] = { required: true };
    __vFields["ipt_apctTelNo"] = { required: true, format: 'phone' };
    __vFields["ipt_apctEmail1"] = { required: true };
    __vFields["ipt_apctEmail2"] = { required: true };
    __vFields["ipt_apctEmail"] = { required: true, format: 'email' };
    __vFields["ipt_coreValuObjNm"] = { required: true };
    __vFields["slc_specyValuIndClssCd"] = { required: true };
    __vFields["cal_valuStrtDd"] = { format: 'date' };
    __vFields["cal_valuSchdlEndDd"] = { format: 'date' };
    __vFields["ipt_onecomApplRsnNm"] = { required: true };
    __vFields["cal_valuStrtDd2"] = { format: 'date' };
