/**
 * @method
 * @name scwin.delAttachFile
 * @author Inswave
 * @date 2026. 09. 06
 * @param fileNo fileSeq strTitle
 * @returns
 * @hidden N
*/
scwin.delAttachFile = function (fileNo, fileSeq, strTitle) {
    let viewDiv = $c.util.getComponent("fileTpCd" + fileNo + fileSeq);
    viewDiv.style.display = "none";
    let editDiv = $c.util.getComponent("Edit-fileTpCd" + fileNo + fileSeq);
    let txt = "";
    txt += "	<input type='file' name='fileTpCd" + fileNo + "[" + (fileSeq - 1) + "]' title='" + strTitle + "' class='w500' size='70'/>";
    txt += "  <br/><span style='color:#52abcc'>* 첨부파일 수정하는 경우 하단의 '수정' 버튼을 선택해야 합니다.</span> ";
    txt += "	<input type='hidden' name='delAttachFileNo' value='" + fileNo + fileSeq + "'/> ";
    editDiv.innerHTML = txt;
    editDiv.style.display = "block";
};


/**
 * @method
 * @name scwin.fn_chkUploadFile
 * @author Inswave
 * @date 2026. 09. 06
 * @param chkSize
 * @returns
 * @hidden N
*/
scwin.fn_chkUploadFile = async function (chkSize) {
    let all_files = $('[type=file]');
    let tmpFile = "";
    let chkSizeM = 20;
    let tmpFileSize = "";
    let tmpFileName = "";
    for (let i = 0; i < all_files.length; i++) {
        tmpFile = all_files[i].files[0];
        if (tmpFile != null && tmpFile !== '') {
            tmpFileSize = all_files[i].files[0].size;
            tmpFileSize = tmpFileSize / (1024 * 1024);
            tmpFileName = all_files[i].files[0].name;
            if (tmpFileSize > chkSize) {
                await $c.win.alert(tmpFileName + " 첨부파일의 사이즈가 " + chkSize + "MB을 넘으면 등록할 수 없습니다. 파일을 확인해주세요.");
                return true;
            }
        }
    }
};


/**
 * @method
 * @name scwin.fn_checkBzRegNo
 * @author Inswave
 * @date 2026. 09. 06
 * @param
 * @returns
 * @hidden N
*/
scwin.fn_checkBzRegNo = async function () {
    let bzRegNo1 = $c.util.getComponent('ipt_bzRegNo1').getValue();
    let bzRegNo2 = $c.util.getComponent('ipt_bzRegNo2').getValue();
    let bzRegNo3 = $c.util.getComponent('ipt_bzRegNo3').getValue();
    let bzRegNo = bzRegNo1 + bzRegNo2 + bzRegNo3;
    if (bzRegNo.length > 0) {
        let subMode = 0;
        subMode += parseInt(bzRegNo.substring(0, 1));
        subMode += parseInt(bzRegNo.substring(1, 2)) * 3 % 10;
        subMode += parseInt(bzRegNo.substring(2, 3)) * 7 % 10;
        subMode += parseInt(bzRegNo.substring(3, 4)) * 1 % 10;
        subMode += parseInt(bzRegNo.substring(4, 5)) * 3 % 10;
        subMode += parseInt(bzRegNo.substring(5, 6)) * 7 % 10;
        subMode += parseInt(bzRegNo.substring(6, 7)) * 1 % 10;
        subMode += parseInt(bzRegNo.substring(7, 8)) * 3 % 10;
        subMode += Math.floor(parseInt(bzRegNo.substring(8, 9)) * 5 / 10);
        subMode += parseInt(bzRegNo.substring(8, 9)) * 5 % 10;
        subMode += parseInt(bzRegNo.substring(9, 10));
        if (subMode % 10 !== 0) {
            await $c.win.alert("사업자등록번호가 잘못되었습니다.");
            return false;
        }
    }
    return true;
};



