/**
 * @method
 * @name scwin.setZipCode_recv
 * @author Inswave
 * @date 2026. 09. 06
 * @param r
 * @returns
 * @hidden N
*/
scwin.setZipCode_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { let rec = a[0]; let nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; let ps = (String(scwin.setZipCode).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); let nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setZipCode.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };
